<script lang="ts">
 import {onMount} from 'svelte';import {companion,updateData} from '../state.svelte';import {canvasContext,loadPicture,observeCanvas} from '../canvas';import {themeAt,appearanceMode} from '../theme';
 let canvas:HTMLCanvasElement,image:HTMLImageElement,loop:ReturnType<typeof observeCanvas>,systemReduced=$state(false),hint=$state('');let x=0,y=0,targetX=0,targetY=0,last=0,pulse=0;
 function move(event:PointerEvent){if(event.pointerType==='touch')return;const box=canvas.getBoundingClientRect();targetX=((event.clientX-box.left)/box.width-.5)*2;targetY=((event.clientY-box.top)/box.height-.5)*2;}
 function toggle(){updateData(data=>data.preferences.islandLight=!data.preferences.islandLight);pulse=performance.now();hint=companion.data.preferences.islandLight?'给你留着一盏小小的灯。':'小岛也准备休息一会儿。';loop?.invalidate();}
 function draw(t:number){if(!image)return;const c=canvasContext(canvas);if(!c)return;const reduced=systemReduced||companion.data.preferences.reduceMotion,dt=Math.min(50,t-(last||t));last=t;const follow=1-Math.exp(-dt/120);x+=(targetX-x)*follow;y+=(targetY-y)*follow;const scale=Math.min(c.width/image.width,c.height*.9/image.height),w=image.width*scale,h=image.height*scale,bob=reduced?0:Math.sin(t/1400)*2.6,dx=(c.width-w)/2+(reduced?0:x*4),dy=(c.height-h)/2+bob+(reduced?0:y*2);c.ctx.imageSmoothingEnabled=true;c.ctx.drawImage(image,dx,dy,w,h);
  if(companion.data.preferences.islandLight){const cx=dx+w*.553,cy=dy+h*.18,glow=c.ctx.createRadialGradient(cx,cy,0,cx,cy,22);glow.addColorStop(0,'#fff5caba');glow.addColorStop(1,'#ffd5a100');c.ctx.fillStyle=glow;c.ctx.fillRect(cx-22,cy-22,44,44);c.ctx.fillStyle='#fff1ba';c.ctx.fillRect(cx-3,cy-2,6,5);}
  if(!reduced&&t-pulse<1600){const p=(t-pulse)/1600;c.ctx.fillStyle='#dcb7e8';for(let i=0;i<7;i++){const a=i*Math.PI*2/7;c.ctx.globalAlpha=1-p;c.ctx.fillRect(c.width*.55+Math.cos(a)*p*45,c.height*.25+Math.sin(a)*p*30,2,2);}c.ctx.globalAlpha=1;}
 }
 $effect(()=>{companion.data.preferences.islandLight;companion.data.preferences.reduceMotion;systemReduced;loop?.invalidate();});
 onMount(()=>{let active=true;loop=observeCanvas(canvas,draw,()=>systemReduced||companion.data.preferences.reduceMotion,0);void loadPicture('/xinyu/generated/sidebar-island-v3.png').then(p=>{if(active){image=p;loop.invalidate();}});const media=matchMedia('(prefers-reduced-motion: reduce)'),changed=()=>systemReduced=media.matches;changed();media.addEventListener('change',changed);return()=>{active=false;loop.destroy();media.removeEventListener('change',changed);};});
</script>
<button class="island-button" aria-label={companion.data.preferences.islandLight?'熄灭小岛灯塔':'点亮小岛灯塔'} aria-pressed={companion.data.preferences.islandLight===true} onclick={toggle} onpointermove={move} onpointerleave={()=>{targetX=0;targetY=0;}}><canvas bind:this={canvas} aria-hidden="true"></canvas><span>心有小岛</span><small>{hint||'轻点灯塔，留一盏温柔的灯'}</small></button>
<style>.island-button{display:block;width:100%;border:0;padding:0 0 10px;background:transparent;color:var(--xy-ink);border-radius:10px;text-align:center;cursor:pointer;touch-action:manipulation}.island-button canvas{display:block;width:100%;height:136px}.island-button>span{display:block;font-size:14px;line-height:1.8}.island-button>small{display:block;font-size:12px;color:var(--xy-secondary);padding:0 5px;margin-top:3px;line-height:1.7}</style>
